function collect({ previousState, body, statusCode, bodyEncoding }) {
  const state = previousState === null ? { page: 1, tickets: [], count: null } : previousState;
  if (!state || !Number.isInteger(state.page) || !Array.isArray(state.tickets))
    throw Error("Invalid search state");
  if (previousState !== null) {
    if (
      statusCode < 200 ||
      statusCode >= 300 ||
      bodyEncoding !== null ||
      !body ||
      !Array.isArray(body.results) ||
      !Number.isInteger(body.count) ||
      body.count < 0
    )
      throw Error("Zendesk search failed or returned an invalid page");
    if (body.count > 1000) throw Error("Zendesk search exceeds the 1000-result limit");
    if (state.count !== null && state.count !== body.count)
      throw Error("Zendesk search changed while paging");
    const ids = new Set(state.tickets.map((t) => t.id));
    for (const ticket of body.results) {
      if (
        !ticket ||
        !Number.isSafeInteger(ticket.id) ||
        ticket.id < 1 ||
        typeof ticket.url !== "string" ||
        typeof ticket.status !== "string" ||
        typeof ticket.subject !== "string" ||
        ids.has(ticket.id)
      )
        throw Error("Invalid or duplicate Zendesk ticket");
      ids.add(ticket.id);
      state.tickets.push({
        id: ticket.id,
        url: ticket.url,
        status: ticket.status,
        subject: ticket.subject,
      });
    }
    state.count = body.count;
    if (
      state.tickets.length > state.count ||
      (body.next_page == null && state.tickets.length !== state.count) ||
      (body.next_page != null && body.results.length === 0)
    )
      throw Error("Incomplete Zendesk search");
    if (body.next_page == null)
      return {
        state,
        more: false,
        query: {
          query: "type:ticket assignee:none status<pending",
          per_page: 100,
          page: state.page,
        },
        tickets: state.tickets,
      };
    if (state.page >= 10) throw Error("Zendesk search exceeds the 1000-result limit");
    state.page++;
  }
  return {
    state,
    more: true,
    query: { query: "type:ticket assignee:none status<pending", per_page: 100, page: state.page },
    tickets: state.tickets,
  };
}

function summarize({ tickets }) {
  if (!Array.isArray(tickets)) throw Error("Expected Zendesk tickets");
  const escape = (value) =>
    value
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replace(/[\r\n]+/g, " ")
      .replace(/[*_~`]/g, (char) => ({ "*": "＊", _: "＿", "~": "～", "`": "｀" })[char]);
  let message = "*Unassigned Tickets*\n\n";
  for (const t of tickets) {
    if (
      !t ||
      !Number.isSafeInteger(t.id) ||
      t.id < 1 ||
      typeof t.url !== "string" ||
      typeof t.status !== "string" ||
      typeof t.subject !== "string"
    )
      throw Error("Invalid Zendesk ticket");
    const match = /^https:\/\/([a-z0-9-]+\.zendesk\.com)\/api\/v2\/tickets\/(\d+)\.json$/i.exec(
      t.url,
    );
    if (!match || Number(match[2]) !== t.id) throw Error("Invalid ticket URL");
    message += `*<https://${match[1]}/agent/tickets/${t.id}|${t.id}>* [${escape(t.status.toUpperCase())}] - ${escape(t.subject)}\n`;
  }
  if (message.length > 40000) throw Error("Slack message exceeds 40000 characters");
  return { message, hasTickets: tickets.length > 0 };
}

let state = collect({
    previousState: null,
    body: null,
    statusCode: null,
    bodyEncoding: null,
  }).state,
  result;
for (const item of $input.all()) {
  result = collect({
    previousState: state,
    body: item.json.body,
    statusCode: item.json.statusCode,
    bodyEncoding: null,
  });
  state = result.state;
}
if (!result || result.more) throw Error("Incomplete Zendesk search");
const summary = summarize({ tickets: result.tickets });
return summary.hasTickets ? [{ json: summary }] : [];
